using System; using ZombieDiner.Orders; public static class OrderMakingEvents{public static event Action<ItemSO> IngredientAdded; public static event Action<DishSO> DishCompleted; public static event Action PlateCleared; public static event Action OrderDeliveredCorrect; public static event Action OrderDeliveredWrong; public static void RaiseIngredientAdded(ItemSO i)=>IngredientAdded?.Invoke(i); public static void RaiseDishCompleted(DishSO d)=>DishCompleted?.Invoke(d); public static void RaisePlateCleared()=>PlateCleared?.Invoke(); public static void RaiseOrderDeliveredCorrect()=>OrderDeliveredCorrect?.Invoke(); public static void RaiseOrderDeliveredWrong()=>OrderDeliveredWrong?.Invoke();}